CREATE TABLE pipeline_triage_results (id UUID PRIMARY KEY,pipeline_run_id UUID NOT NULL REFERENCES pipeline_runs(id) ON DELETE CASCADE,primary_failure_event_id UUID,primary_fingerprint VARCHAR(64),primary_classification VARCHAR(64),rerun_recommendation VARCHAR(32) NOT NULL,rerun_confidence DOUBLE PRECISION NOT NULL,summary TEXT NOT NULL,triage_version VARCHAR(32) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_triage_version UNIQUE(pipeline_run_id,triage_version));
CREATE TABLE failure_triage_entries (id UUID PRIMARY KEY,triage_result_id UUID NOT NULL REFERENCES pipeline_triage_results(id) ON DELETE CASCADE,failure_event_id UUID NOT NULL REFERENCES failure_events(id),fingerprint VARCHAR(64) NOT NULL,failure_role VARCHAR(32) NOT NULL,importance_score DOUBLE PRECISION NOT NULL);
